echo 'export HTTP_PROXY="http://30.156.74.28:8080"' >> ~/.bashrc && source ~/.bashrc
curl -sS -D /tmp/python-best-practices-headers.txt http://127.0.0.1:8000/content/python-best-practices-page -o /tmp/python-best-practices.html
printf '%s\n' '--- headers ---'
sed -n '1,20p' /tmp/python-best-practices-headers.txt
printf '%s\n' '--- title ---'
rg -o '<title[^>]*>[^<]*' /tmp/python-best-practices.html || true
printf '%s\n' '--- body text ---'
python - <<'PY'
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self): super().__init__(); self.out=[]; self.skip=0
    def handle_starttag(self,t,a):
        if t in ('script','style'): self.skip+=1
        if not self.skip and t in ('h1','h2','h3','h4','h5','h6','p','li','dt','dd','pre','blockquote'): self.out.append(('OPEN',t))
    def handle_endtag(self,t):
        if t in ('script','style') and self.skip: self.skip-=1
        if not self.skip and t in ('h1','h2','h3','h4','h5','h6','p','li','dt','dd','pre','blockquote'): self.out.append(('CLOSE',t))
    def handle_data(self,d):
        if not self.skip and d.strip(): self.out.append(('TEXT',' '.join(d.split())))
p=P(); p.feed(open('/tmp/python-best-practices.html', encoding='utf-8').read())
for kind,val in p.out:
    if kind=='TEXT': print(val)
PY

